        status.pointer.write(0, buffer.getByteArray(0, size), 0, size)
        status.read()
        buffer.setByte(0, UNIFFI_CALL_SUCCESS)
        return status
    }
}

// Helpers for calling Rust
// In practice we usually need to be synchronized to call this safely, so it doesn't
