/**
 * Errors returned to Kotlin.
 */
sealed class FfiException: kotlin.Exception() {
    
    /**
     * Input could not be parsed.
     */
    class Malformed(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * Input exceeds a size limit.
     */
    class TooLarge(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * Unknown format version.
     */
    class UnsupportedVersion(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * Signature, MAC or AEAD failure.
     */
    class BadSignature(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * Expired object.
     */
    class Expired(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * Object not valid yet.
     */
    class NotYetValid(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * Not authorised.
     */
    class Unauthorized(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * Not anchored to a trusted root.
     */
    class Untrusted(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * Sphinx failure.
     */
    class Sphinx(
        ) : FfiException() {
        override val message
            get() = ""
    }
    
    /**
     * Wrong argument length or state (e.g. handshake used twice).
     */
    class InvalidArgument(
        ) : FfiException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {
        

        return when(buf.getInt()) {
            1 -> FfiException.Malformed()
            2 -> FfiException.TooLarge()
            3 -> FfiException.UnsupportedVersion()
            4 -> FfiException.BadSignature()
            5 -> FfiException.Expired()
            6 -> FfiException.NotYetValid()
            7 -> FfiException.Unauthorized()
            8 -> FfiException.Untrusted()
            9 -> FfiException.Sphinx()
            10 -> FfiException.InvalidArgument()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiException): ULong {
        return when(value) {
            is FfiException.Malformed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.TooLarge -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.UnsupportedVersion -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.BadSignature -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Expired -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.NotYetValid -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Unauthorized -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Untrusted -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.Sphinx -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiException.InvalidArgument -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.Malformed -> {
                buf.putInt(1)
                Unit
            }
            is FfiException.TooLarge -> {
                buf.putInt(2)
                Unit
            }
            is FfiException.UnsupportedVersion -> {
                buf.putInt(3)
                Unit
            }
            is FfiException.BadSignature -> {
                buf.putInt(4)
                Unit
            }
            is FfiException.Expired -> {
                buf.putInt(5)
                Unit
            }
            is FfiException.NotYetValid -> {
                buf.putInt(6)
                Unit
            }
            is FfiException.Unauthorized -> {
                buf.putInt(7)
                Unit
            }
            is FfiException.Untrusted -> {
                buf.putInt(8)
                Unit
            }
            is FfiException.Sphinx -> {
                buf.putInt(9)
                Unit
            }
            is FfiException.InvalidArgument -> {
                buf.putInt(10)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



