/**
 * Messages a phone can receive (anything else decodes as `Other`).
 */
sealed class FfiMessage {
    
    /**
     * Answer to FETCH.
     */
    data class FetchResponse(
        /**
         * Blobs.
         */
        val `blobs`: List<app.harpochat.core.FfiBlob>, 
        /**
         * More are waiting.
         */
        val `more`: kotlin.Boolean) : FfiMessage()
        
    {
        

        companion object
    }
    
    /**
     * Real-time push.
     */
    data class Push(
        /**
         * Source mailbox.
         */
        val `mailboxId`: kotlin.ByteArray, 
        /**
         * Blobs.
         */
        val `blobs`: List<app.harpochat.core.FfiBlob>) : FfiMessage()
        
    {
        

        companion object
    }
    
    /**
     * Mail is waiting.
     */
    data class Notify(
        /**
         * Mailbox.
         */
        val `mailboxId`: kotlin.ByteArray, 
        /**
         * Pending blobs.
         */
        val `pending`: kotlin.UShort) : FfiMessage()
        
    {
        

        companion object
    }
    
    /**
     * A LOOP cover message came back.
     */
    object Loop : FfiMessage()
    
    
    /**
     * Valid envelope not meant for a phone.
     */
    data class Other(
        /**
         * Spec §8 type code.
         */
        val `typeCode`: kotlin.UByte) : FfiMessage()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiMessage : FfiConverterRustBuffer<FfiMessage>{
    override fun read(buf: ByteBuffer): FfiMessage {
        return when(buf.getInt()) {
            1 -> FfiMessage.FetchResponse(
                FfiConverterSequenceTypeFfiBlob.read(buf),
                FfiConverterBoolean.read(buf),
                )
            2 -> FfiMessage.Push(
                FfiConverterByteArray.read(buf),
                FfiConverterSequenceTypeFfiBlob.read(buf),
                )
            3 -> FfiMessage.Notify(
                FfiConverterByteArray.read(buf),
                FfiConverterUShort.read(buf),
                )
            4 -> FfiMessage.Loop
            5 -> FfiMessage.Other(
                FfiConverterUByte.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiMessage): ULong = when(value) {
        is FfiMessage.FetchResponse -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceTypeFfiBlob.allocationSize(value.`blobs`)
                + FfiConverterBoolean.allocationSize(value.`more`)
            )
        }
        is FfiMessage.Push -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.`mailboxId`)
                + FfiConverterSequenceTypeFfiBlob.allocationSize(value.`blobs`)
            )
        }
        is FfiMessage.Notify -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.`mailboxId`)
                + FfiConverterUShort.allocationSize(value.`pending`)
            )
        }
        is FfiMessage.Loop -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is FfiMessage.Other -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUByte.allocationSize(value.`typeCode`)
            )
        }
    }

    override fun write(value: FfiMessage, buf: ByteBuffer) {
        when(value) {
            is FfiMessage.FetchResponse -> {
                buf.putInt(1)
                FfiConverterSequenceTypeFfiBlob.write(value.`blobs`, buf)
                FfiConverterBoolean.write(value.`more`, buf)
                Unit
            }
            is FfiMessage.Push -> {
                buf.putInt(2)
                FfiConverterByteArray.write(value.`mailboxId`, buf)
                FfiConverterSequenceTypeFfiBlob.write(value.`blobs`, buf)
                Unit
            }
            is FfiMessage.Notify -> {
                buf.putInt(3)
                FfiConverterByteArray.write(value.`mailboxId`, buf)
                FfiConverterUShort.write(value.`pending`, buf)
                Unit
            }
            is FfiMessage.Loop -> {
                buf.putInt(4)
                Unit
            }
            is FfiMessage.Other -> {
                buf.putInt(5)
                FfiConverterUByte.write(value.`typeCode`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





